import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility;
import org.junit.jupiter.api.Test;

class PinnedScalarEffectsCompositionTest {
	private static final String URI = "urn:test:pinned-scalar-effects-composition";

	@Test
	void effectUsesPinnedImplementationAfterRegistryReplacement() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.get(URI).orElse(null);
		Function stable = implementation(Function.Determinism.DETERMINISTIC, false);
		Function volatileReplacement = implementation(Function.Determinism.VOLATILE, true);
		registry.add(stable);
		try {
			Filter root = new Filter(new SingletonSet(), call());
			QueryEvaluationUtility.pinFunctions(root);
			FunctionCall pinned = (FunctionCall) root.getCondition();
			assertSame(stable, QueryEvaluationUtility.resolveFunction(pinned).orElseThrow());
			registry.add(volatileReplacement);
			assertSame(stable, QueryEvaluationUtility.resolveFunction(pinned).orElseThrow());
			assertEquals(REPEATABLE, ScalarEvaluationEffects.effectOf(pinned));
			assertEquals(VOLATILE, ScalarEvaluationEffects.effectOf(call()));
		} finally {
			registry.remove(volatileReplacement);
			registry.remove(stable);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	@Test
	void explicitVolatilityIsIndependentOfFreshnessGuarantee() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.get(URI).orElse(null);
		Function volatileFunction = implementation(Function.Determinism.VOLATILE, false);
		registry.add(volatileFunction);
		try {
			assertEquals(VOLATILE, ScalarEvaluationEffects.effectOf(call()));
		} finally {
			registry.remove(volatileFunction);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	private static FunctionCall call() {
		return new FunctionCall(URI, new ValueConstant(SimpleValueFactory.getInstance().createLiteral("input")));
	}

	private static Function implementation(Function.Determinism determinism, boolean fresh) {
		return new Function() {
			@Override
			public String getURI() {
				return URI;
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				return valueFactory.createLiteral("result");
			}

			@Override
			public Determinism getDeterminism() {
				return determinism;
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return fresh;
			}
		};
	}
}
